questionvariables.text:
/* Illustrative three-variety version of the Osun/Benue example. */
idstart:rand(70)+101;
osun_each:rand(4)+8;
benue_a:rand(3)+2;
benue_b:rand(3)+5;
benue_c:rand(3)+10;

osun_total:3*osun_each;
benue_total:benue_a+benue_b+benue_c;
pooled_a:osun_each+benue_a;
pooled_b:osun_each+benue_b;
pooled_c:osun_each+benue_c;
grand_total:osun_total+benue_total;

/* Choices are shuffled; the integer keys are the assessed answers. */
tapredict:random_permutation([
 [1,true,"The pooled table combines observations from two trials that have different frequency patterns."],
 [2,false,"A frequency table is never useful for a factor variable."],
 [3,false,"A pooled table always contains fewer observations than either trial."],
 [4,false,"The ID numbers prove that some farmers have been counted twice."]
]);
taidpart:random_permutation([
 [1,true,"The text before the hyphen (Osun or Benue)."],
 [2,false,"The digits after the hyphen."],
 [3,false,"The name of the variety in option_a."],
 [4,false,"The number of letters in the ID."]
]);
tatrialtype:random_permutation([
 [1,true,"Factor, with levels Osun and Benue."],
 [2,false,"Numeric, because the trial name appears in an ID."],
 [3,false,"Ordered factor, because Osun must come before Benue."],
 [4,false,"A measured quantity obtained by averaging the IDs."]
]);
taosuninterpret:random_permutation([
 [1,true,"The three varieties have equal frequencies in the Osun subset."],
 [2,false,"Variety C has the highest frequency in the Osun subset."],
 [3,false,"The Osun subset includes all Benue farmers."],
 [4,false,"Filtering to Osun makes option_a a numeric variable."]
]);
tanextstep:random_permutation([
 [1,true,"Create a trial factor and compare option_a frequencies separately by trial."],
 [2,false,"Delete the trial information and compare only the pooled totals."],
 [3,false,"Calculate the mean of the ID column."],
 [4,false,"Treat the pooled counts as if they came from one trial."]
]);
